      { npc: "\u4EBA\u4EEC\u96C6\u4E2D\u751F\u6D3B\u5728\u5B89\u5168\u8857\u533A\u3002\u90A3\u4E9B\u7A97\u6237\u9EDD\u9ED1\u7684\u5927\u53A6\u4ECE\u6765\u6CA1\u6709\u5F00\u8FC7\u95E8\uFF0C\u522B\u5728\u95E8\u53E3\u6D6A\u8D39\u529B\u6C14\u3002", opts: [{ text: "\u6211\u77E5\u9053\u4E86\u3002", action: "leave" }] }
