    stage("\u505C\u9760\u8BB0\u5F55", "\u8BB0\u5F55 Level 5 \u7684\u4E24\u4E2A\u505C\u9760\u70B9\u3002", record(5, 2)),
    stage("\u8FD0\u8425\u590D\u6838", "\u56DE EL3A \u4EA4\u7ED9\u60E0\u7279\u83F2\u5C14\u5FB7\u3002", talk("whitfield"))
