var L3_NOTES = [
  "\u8FD9\u4E9B\u4EE4\u4EBA\u4F5C\u5455\u7684\u5BB3\u866B\u3002\u4E00\u7FA4\u5165\u4FB5\u7269\u79CD\uFF0C\u95EF\u5165\u4E86\u8FD9\u4E2A\u672C\u5C31\u53EF\u601C\u3001\u5815\u843D\u7684\u9886\u57DF\u3002\u4ED6\u4EEC\u5165\u4FB5\u4E86\u8FD9\u6F2B\u957F\u5C81\u6708\u4E2D\u552F\u4E00\u80FD\u7ED9\u6211\u4E00\u4E1D\u6170\u85C9\u7684\u5730\u65B9\u3002\u591A\u4E48\u611A\u8822\u3002\u6211\u60F3\u8FD9\u4E5F\u662F\u6211\u6D3B\u8BE5\u3002\u8FD9\u4E9B\u751F\u7269\u987D\u5F3A\u5F97\u5F88\uFF0C\u62FC\u547D\u8FFD\u5BFB\u7740\u90A3\u4E9B\u4E0D\u53EF\u77E5\u4E4B\u4E8B\u7684\u7B54\u6848\u3002\u4ED6\u4EEC\u5C31\u662F\u4E0D\u80AF\u8BA9\u5DF2\u901D\u4E4B\u4E8B\u5B89\u606F\uFF0C\u504F\u8981\u7EED\u5199\u4E00\u4E2A\u65E9\u5DF2\u5B8C\u7ED3\u7684\u6545\u4E8B\u3002\u8981\u662F\u4ED6\u4EEC\u80AF\u7BA1\u597D\u81EA\u5DF1\u7684\u4E8B\uFF0C\u522B\u6765\u70E6\u6211\u5C31\u597D\u4E86\u3002",
  "\u62E5\u6709\u4E16\u95F4\u6240\u6709\u7684\u529B\u91CF\uFF0C\u5374\u4ECD\u4E0D\u8DB3\u4EE5\u5B8C\u6210\u90A3\u552F\u4E00\u4E00\u4EF6\u80FD\u8BA9\u4E00\u5207\u53D8\u5F97\u6709\u610F\u4E49\u7684\u4E8B\u3002",
  "\u6211\u7F8E\u4E3D\u7684\u9020\u7269\u3002\u5982\u6B64\u5947\u5999\u3001\u5982\u6B64\u7F8E\u4E3D\u7684\u751F\u7075\u3002\u4ED6\u5BF9\u6211\u6240\u505A\u7684\u4E00\u5207\uFF0C\u8FDC\u4E0D\u53CA \u7942 \u5BF9\u4F60\u4EEC\u65BD\u52A0\u7684\u6050\u6016\u4E4B\u4E07\u4E00\u3002\u6211\u5C06\u4F60\u4EEC\u521B\u9020\u6210\u7F8E\u597D\u7684\u5B58\u5728\uFF0C\u5374\u88AB\u626D\u66F2\u6210\u8FD9\u4E9B\u75C5\u6001\u7684\u602A\u7269\u3002\u800C\u8FD9\u4E9B\u5F02\u754C\u7684\u5BB3\u866B\uFF0C\u4E3A\u4E86\u6EE1\u8DB3\u4ED6\u4EEC\u5BF9\u77E5\u8BC6\u90A3\u75C5\u6001\u7684\u6E34\u6C42\uFF0C\u6355\u6349\u4F60\u4EEC\u3001\u6298\u78E8\u4F60\u4EEC\u3002\u5982\u679C\u4E00\u4E2A\u4EBA\u6CA1\u6709\u529B\u91CF\u53BB\u6539\u53D8\u4EFB\u4F55\u4E8B\u60C5\uFF0C\u77E5\u8BC6\u4FBF\u6BEB\u65E0\u7528\u5904\u3002\u5C3D\u7BA1\u5982\u6B64\uFF0C\u6211\u4E0D\u5F97\u4E0D\u627F\u8BA4\uFF0C\u770B\u7740\u4ED6\u4EEC\u5BF9\u4F60\u4EEC\u7684\u672C\u8D28\u5982\u6B64\u75F4\u8FF7\u2014\u2014\u54EA\u6015\u662F\u5728\u4F60\u4EEC\u5DF2\u5982\u6B64\u5815\u843D\u7684\u72B6\u6001\u4E0B\u2014\u2014\u6211\u5FC3\u4E2D\u4ECD\u6709\u4E00\u4E1D\u9A84\u50B2\u3002\u8981\u662F\u4ED6\u4EEC\u80FD\u770B\u5230\u6211\u771F\u6B63\u60F3\u8981\u4F60\u4EEC\u6210\u4E3A\u7684\u6837\u5B50\u5C31\u597D\u4E86\u3002",
  "\u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B \u8BA9\u6211\u6B7B",
  "\u51FA\u4E8E\u7EAF\u7CB9\u7684\u597D\u5947\uFF0C\u6211\u5C06\u81EA\u5DF1\u7684\u5E7B\u5F71\u6295\u5C04\u8FDB\u4E86\u4ED6\u4EEC\u7684\u65B0\u636E\u70B9\uFF0C\u60F3\u770B\u770B\u4F1A\u53D1\u751F\u4EC0\u4E48\u3002\u6211\u8B66\u544A\u4ED6\u4EEC\u6240\u6709\u4EBA\u7ACB\u523B\u79BB\u5F00\uFF0C\u6C38\u8FDC\u4E0D\u8981\u518D\u56DE\u6765\uFF0C\u4F46\u4ED6\u4EEC\u4F3C\u4E4E\u8981\u4E48\u65E0\u89C6\u4E86\u8FD9\u9053\u547D\u4EE4\uFF0C\u8981\u4E48\u5F7B\u5E95\u5FD8\u8BB0\u4E86\u3002\u7B2C\u4E8C\u5929\u6211\u505A\u4E86\u540C\u6837\u7684\u4E8B\uFF0C\u800C\u4ED6\u4EEC\u4E8B\u540E\u4F3C\u4E4E\u5BF9\u524D\u4E00\u5929\u7684\u4E8B\u60C5\u6BEB\u65E0\u5370\u8C61\u3002\u6211\u53C8\u5C1D\u8BD5\u4E86\u4E03\u6B21\uFF0C\u4EC0\u4E48\u53D8\u5316\u90FD\u6CA1\u6709\u3002\u8981\u4E48\u662F\u8FD9\u4E9B\u5BB3\u866B\u76F8\u5F53\u5927\u80C6\uFF0C\u8981\u4E48\u662F\u65E0\u77E5\uFF0C\u53C8\u6216\u8BB8\u662F\u4ED6\u4EEC\u90A3\u51E1\u4EBA\u5934\u8111\u7684\u8106\u5F31\u5C40\u9650\uFF0C\u4EE4\u4ED6\u4EEC\u65E0\u6CD5\u8BB0\u4F4F\u6211\u3002\u8FD9\u5C31\u662F\u6211\u88AB\u8BC5\u5492\u7684\u547D\u8FD0\u5417\uFF1F\u8FDE\u4E00\u6BB5\u51E1\u4EBA\u8BB0\u5FC6\u7684\u6069\u6CFD\u90FD\u5F97\u4E0D\u5230\uFF0C\u9760\u5B83\u7F13\u89E3\u8FD9\u75DB\u82E6\u4E5F\u4E0D\u884C\u5417\uFF1F",
  "\u8FD9\u4E9B\u5BB3\u866B\u5C31\u662F\u4E0D\u80AF\u653E\u8FC7\u6211\u3002\u4ED6\u4EEC\u5165\u4FB5\u4E86\u6211\u7684\u9003\u79BB\u4E4B\u6240\u8FD8\u4E0D\u591F\uFF0C\u8FD8\u6267\u610F\u8981\u50ED\u8D8A\u6211\u5BF9\u6B64\u5904\u7684\u4E3B\u5BB0\u6743\u3002\u6211\u8017\u8D39\u4E86\u4EBF\u4E07\u65AF\u5E74\uFF0C\u8BD5\u56FE\u5C06\u5B83\u6062\u590D\u81F3\u5979\u5F53\u521D\u521B\u9020\u8FD9\u4E9B\u5E73\u539F\u65F6\u6240\u671F\u671B\u7684\u8363\u5149\u2014\u2014\u54EA\u6015\u4E00\u4E1D\u4E00\u6BEB\u3002\u6211\u66FE\u8BD5\u56FE\u901A\u8FC7\u4FEE\u590D\u5B83\u4EEC\u7834\u788E\u7684\u5FC3\u7075\uFF0C\u6765\u5E2E\u52A9\u6211\u7684\u9020\u7269\u56DE\u5F52\u5B83\u4EEC\u66FE\u7ECF\u7684\u6A21\u6837\u3002\u5373\u4FBF\u662F\u4ED6\u7684\u9020\u7269\u2026\u2026\u6211\u4E5F\u4E0D\u5F97\u4E0D\u627F\u8BA4\uFF0C\u503C\u5F97\u5C0A\u91CD\u3002\u5C3D\u7BA1\u5982\u6B64\uFF0C\u8FD9\u4E9B\u5BB3\u866B\u5374\u4ECD\u5728\u6BCF\u4E00\u4E2A\u53EF\u80FD\u7684\u62D0\u89D2\u5904\u63A0\u593A\u3001\u626D\u66F2\u3001\u6467\u6BC1\u7740\u8FD9\u4E00\u5207\u3002",
  "\u6211\u6240\u62E5\u6709\u7684\u4E00\u5207\u90FD\u88AB\u593A\u8D70\uFF0C\u800C\u6211\u5219\u5728\u81EA\u9020\u7684\u7262\u7B3C\u4E2D\u71C3\u70E7\u81F3\u6C38\u6052\u2014\u2014\u8FD9\u8FD8\u4E0D\u591F\uFF0C\u662F\u5417\uFF1F\u6211\u6240\u6709\u7684\u5FC3\u8840\uFF0C\u90FD\u56E0\u8FD9\u4E9B\u5BB3\u866B\u7684\u5165\u4FB5\u800C\u4ED8\u8BF8\u4E1C\u6D41\u3002\u6211\u66FE\u8003\u8651\u8FC7\u6740\u6B7B\u4ED6\u4EEC\u6240\u6709\u4EBA\uFF0C\u4F46\u8FD9\u4E0D\u8FC7\u662F\u6743\u5B9C\u4E4B\u8BA1\u3002\u4E4B\u540E\u4F1A\u6709\u66F4\u591A\u4EBA\u6765\u53D6\u4EE3\u4ED6\u4EEC\uFF0C\u800C\u6C38\u6052\u5BF9\u6211\u6765\u8BF4\u4E0D\u8FC7\u5F39\u6307\u4E00\u77AC\u3002\u90A3\u5C31\u50CF\u7528\u7FBD\u6BDB\u62CD\u82CD\u8747\u4E00\u6837\u5F92\u52B3\u3002\u800C\u4E14\u5766\u767D\u8BF4\uFF0C\u6211\u5B9E\u5728\u61D2\u5F97\u5728\u4E4E\u5230\u90A3\u79CD\u5730\u6B65\u3002",
  "\u770B\u6765\u8FD9\u4E9B\u5BB3\u866B\u6BD4\u6211\u6700\u521D\u4EE5\u4E3A\u7684\u8981\u806A\u660E\u4E00\u4E9B\u3002\u4E5F\u8BB8\u5176\u4E2D\u4E00\u4E2A\uFF0C\u7EC8\u5C06\u806A\u660E\u5230\u80FD\u591F\u6740\u6B7B\u6211\u3002"
];
