var thingSkinTextures = null;
function getThingSkinTextures() {
  if (thingSkinTextures) return thingSkinTextures;
  const n = 256;
  const rgba = new Uint8Array(n * n * 4);
  const height = new Uint8Array(n * n * 4);
  const hash2 = (x, y) => {
    let h = Math.imul(x ^ 2654435769, 2246822507) ^ Math.imul(y ^ 3266489909, 668265263);
    h ^= h >>> 15;
    h = Math.imul(h, 739982445);
    h ^= h >>> 12;
    return (h >>> 0) / 4294967295;
  };
  const rot = [[38, 46, 17], [119, 89, 24], [203, 37, 14], [221, 179, 27], [72, 198, 19]];
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const p = (y * n + x) * 4;
    const fine = hash2(x, y) - 0.5;
    const coarse = hash2(x >> 3, y >> 3) - 0.5;
    const fold = Math.sin(y * 0.34 + Math.sin(x * 0.075) * 2.4) * 0.5 + 0.5;
    const scale = Math.sin(x * 0.052 + Math.sin(y * 0.031) * 2.1) * 0.5 + 0.5;
    let r = 61 + fine * 23 + coarse * 28 + fold * 9;
    let g = 62 + fine * 20 + coarse * 23 + scale * 7;
    let b2 = 51 + fine * 15 + coarse * 15;
    let bh = 108 + fine * 72 + fold * 32 + scale * 18;
    const scar = Math.abs((x * 0.83 + y * 0.29 + Math.sin(y * 0.12) * 9) % 91 - 45.5);
    if (scar < 2.1 && (x + y * 3) % 157 < 104) {
      const k = 1 - scar / 2.1;
      r += 54 * k;
      g += 50 * k;
      b2 += 38 * k;
      bh += 58 * k;
      if (scar < 0.55) {
        r -= 48;
        g -= 43;
        b2 -= 31;
        bh -= 92;
      }
    }
    for (const [cx, cy, rad] of rot) {
      const dx0 = Math.abs(x - cx), dy0 = Math.abs(y - cy);
      const dx = Math.min(dx0, n - dx0), dy = Math.min(dy0, n - dy0);
      const d = Math.hypot(dx * 1.25, dy);
      if (d < rad + Math.sin(Math.atan2(dy, dx || 0.01) * 7) * 3) {
        const k = 1 - d / rad;
        r -= 34 + k * 22;
        g -= 35 + k * 26;
        b2 -= 22 + k * 12;
        bh -= 45 + k * 48;
        if (d > rad * 0.72) {
          r += 31;
          g += 15;
          b2 += 8;
        }
      }
    }
    rgba[p] = Math.max(8, Math.min(155, r));
    rgba[p + 1] = Math.max(8, Math.min(150, g));
    rgba[p + 2] = Math.max(7, Math.min(125, b2));
    rgba[p + 3] = 255;
    const hv = Math.max(4, Math.min(245, bh));
    height[p] = height[p + 1] = height[p + 2] = hv;
    height[p + 3] = 255;
  }
  const color = new DataTexture(rgba, n, n, RGBAFormat);
  color.colorSpace = SRGBColorSpace;
  color.wrapS = color.wrapT = RepeatWrapping;
  color.repeat.set(2.6, 1.45);
  color.magFilter = LinearFilter;
  color.minFilter = LinearMipmapLinearFilter;
  color.generateMipmaps = true;
  color.anisotropy = 4;
  color.needsUpdate = true;
  const bump = new DataTexture(height, n, n, RGBAFormat);
  bump.wrapS = bump.wrapT = RepeatWrapping;
  bump.repeat.copy(color.repeat);
  bump.magFilter = LinearFilter;
  bump.minFilter = LinearMipmapLinearFilter;
  bump.generateMipmaps = true;
  bump.anisotropy = 4;
  bump.needsUpdate = true;
  thingSkinTextures = { color, bump };
  return thingSkinTextures;
}
